def the_passover_at_the_place(case, data):
    """F1 — Deut 16:1-8 — THE LINE passover_at_the_place_declared writing passover_at_the_place_commanded and seventh_day_assembly_commanded (STATUSES), passover_in_the_gates_barred, leaven_with_the_passover_barred and flesh_till_morning_barred (BLOCKS); the intercalation, the party of one, the three phrases, the intermediate days' work PARAMETERS; the Passover's own procedure by CALL (pesach, moadim, musafim, calendar, erection); Mishnah Berakhot 1:5, Pesachim 3:7, Beitzah 1:1 the exam rows"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_intercalation':
        ink('16:1', '"OBSERVE THE MONTH OF AVIV" — the chapter\'s first word the one infinitive absolute %s; "the month of Aviv" %s (Exodus 23:15, 34:18 the twins — 16:1\'s closest kin %s)' % (INF_ABS, P('חדש', 'האביב', books=None), KINC[1][0]))
        move('the Sifrei 127:1 (read whole at the reading); calendar_parameters.yaml intercalated_month, intercalation_grounds, intercalation_threshold_days (the registry by CALL) — %s, %s, %s; exercised_by %s' % (CAL_LEAP, CAL_GROUNDS, CAL_THRESH, CAL_LEAP_BY), "'observe the month near to Aviv, that Aviv fall in its season' — THE INTERCALATION READ OUT OF 'OBSERVE': the leap month a law of THIS verse; the calendar's rows on file for the COUNT era alone (Sanhedrin 12b's Adar, 13a's sixteen days, 11b's three grounds — the season ground modeled); the exodus era's Aviv NOT ON THE RUNNING TAPE — OWED to the full process (the debt line)")
        dat('THE PARAMETER the_intercalation (the registry\'s three rows for the count era; the exodus era\'s Aviv owed); the exam\'s person the court that adds a thirteenth month when the season falls short by sixteen days — accepted')
        return out("the intercalation (16:1) — 'observe the month near to Aviv' (the Sifrei 127:1): the leap month the calendar's rows for the count era by CALL (Adar doubled, thirty days, the sixteen-day threshold, the three grounds), the exodus era's Aviv owed: the court that adds the thirteenth month accepted", ['accepted'])
    if ask == 'the_passovers_name':
        ink('16:1-2', '"and you shall make the Passover … and you shall sacrifice the Passover" — the Passover\'s four seats in the chapter %s; the consonantal census carries "lame" (15:21, Leviticus 21:18 — told apart by lemma)' % ([s for s in PESACH if s.startswith('Deut 16')],))
        move('the Sifrei 128:1-2 (read whole at the reading); cold_run_pesach (CALL) — PS.paschal_procedure(for_its_sake) = %s' % (PS_NAME,), "THAT ITS MAKING BE FOR THE NAME OF THE PASSOVER — not for its name, disqualified (128:1; Mishnah Zevachim 1:1's exception, Pesachim 5:2 the exam owed); the four services take the name, the roasting and the rinsing do not (128:2 — I8's shape); the pesach engine's own cell by CALL")
        dat('the name a DATA row (the_passovers_name — the four services); the exam\'s person the slaughterer who slaughters the Passover as a peace offering — disqualified, the offering invalid')
        return out("the Passover's name (16:1-2) — its making for the name of the Passover, not for its name disqualified (the Sifrei 128:1-2; pesach.paschal_procedure('for_its_sake') by CALL: %s): the slaughterer under another name barred from it" % (PS_NAME,), ['barred_from_it'])
    if ask == 'the_flock_and_the_herd':
        ink('16:2', '"FLOCK AND HERD" — the verse %s; Exodus 12:5\'s lamb of the sheep or goats the kin; Onkelos writes the law: "the Passover from the sons of the flock, and the holy slaughterings from the oxen" (asserted at the reading)' % (W16(2)[4:6],))
        move('the Sifrei 129:6 (read whole at the reading); cold_run_erection (CALL) — ER.repeats(chagigah_overnight) = %s' % (ER_CHAG,), "FLOCK FOR THE PASSOVER AND HERD FOR THE FESTIVAL OFFERING (129:6 — the herd a second offering, the Passover Exodus 12:5's lamb upheld; another word: every obligation from unconsecrated beasts as the Passover — Mishnah Menachot 7:6); the fourteenth's festival offering not overnight the erection's reading of Exodus 34:25 by CALL")
        dat('the flock and the herd a DATA row (the_flock_and_the_herd — the herd the festival offering, Onkelos concurring); the exam\'s person the one who brings the Passover from the herd — barred from it (the Passover from the flock alone)')
        return out("flock and herd (16:2) — flock for the Passover, herd for the festival offering (the Sifrei 129:6; Onkelos 'the holy slaughterings from the oxen'; erection.repeats by CALL: %s): the one who brings the Passover from the herd barred from it" % (ER_CHAG,), ['barred_from_it'])
    if ask == 'the_night_remembered':
        ink('16:3', '"that you may remember the day of your going out of the land of Egypt ALL THE DAYS OF YOUR LIFE" — "remember" %s; "Egypt" in the chapter %s' % ([(v, x) for v in range(1, 23) for x in W16(v) if x in ('תזכר', 'וזכרת')], [(v, x) for v in range(1, 23) for x in W16(v) if 'מצרים' in x]))
        move('the Sifrei 130:4 (read whole at the reading); MISHNAH BERAKHOT 1:5 (read whole at the design — THE EXAM ROW)', "THE NIGHT REMEMBERED — Ben Zoma: 'the days of your life' the days, 'ALL the days of your life' the nights (the exodus mentioned at night — R. Elazar ben Azaryah's seventy years); the sages: 'the days of your life' this world, 'all' brings the days of the Messiah: TWO ARMS on the Mishnah's own line, both recorded")
        dat('the night remembered a DATA row (the_night_remembered — two arms: the nights / the days of the Messiah); the exam\'s person the one who mentions the exodus in the evening Shema — accepted (Ben Zoma\'s arm the practice)')
        return out("the night remembered (16:3) — 'all the days of your life': Ben Zoma's nights against the sages' days of the Messiah (Mishnah Berakhot 1:5 — the exam row read whole; the Sifrei 130:4): two arms, a DATA row; the one who mentions the exodus at night accepted", ['accepted'])
    if ask == 'the_leaven_bans_onset':
        ink('16:3', '"YOU SHALL NOT EAT LEAVEN WITH IT" — the negation %s; "with it" twice %s; the ban\'s seven days %s' % ([x for x in W16(3) if x in NEG_T], [x for x in W16(3) if x == 'עליו'], [s for s in SEVEN if s in ('Deut 16:3', 'Deut 16:4')]))
        move('the Sifrei 130:1 (read whole at the reading); cold_run_moadim (CALL) — MO.passover()[slaughter_window] = %s; cold_run_pesach (CALL) — the window %s' % (MO_WINDOW, CA_MATZAH), "THE BAN'S ONSET FROM THE SIXTH HOUR — R. Judah: whence that one who eats leaven from the sixth hour onward transgresses a prohibition? 'you shall not eat leaven WITH IT' — with the Passover's slaughter, from midday (130:1; Mishnah Pesachim 1:4-5 owed; Pesachim 28b the segment if disputed — not read): THE BLOCK leaven_with_the_passover_barred, its onset a clock datum the slaughter window's after_midday by CALL")
        dat('THE WRITE leaven_with_the_passover_barred — a BLOCK on israel_people at the counter\'s day %s (DH2); its onset the_leaven_bans_onset a clock datum (after midday of the fourteenth — the moadim engine\'s slaughter window); the exam\'s person the one who eats leaven at the seventh hour of the fourteenth — barred from it' % (CLOCK['counter'],))
        return out("the leaven ban's onset (16:3) — 'with it' the slaughter's time, from the sixth hour onward (the Sifrei 130:1; moadim.passover()['slaughter_window'] %s by CALL): THE WRITE leaven_with_the_passover_barred, a BLOCK on Israel at the chapter's own day; the eater at the seventh hour of the fourteenth barred from it" % (MO_WINDOW,), ['leaven_with_the_passover_barred'])
    if ask == 'the_bread_of_affliction':
        ink('16:3', '"seven days you shall eat unleavened bread with it, THE BREAD OF AFFLICTION" — the phrase\'s one seat in the Bible %s; "in haste" %s' % (P('לחם', 'עני', books=None), hits('בחפזון')))
        move('the Sifrei 130:2-3 (read whole at the reading)', "BREAD OF AFFLICTION — to the exclusion of scalded bread and cakes (130:3); 'in haste you went out' the reason clause (130:2 — Exodus 12:11's haste the same word); the bread's kind narrowed by the word (Mishnah Pesachim 2:6 owed)")
        dat('the bread of affliction a DATA row (the_bread_of_affliction — scalded bread and cakes out); the exam\'s person the one who fulfils the duty with a scalded loaf — barred from it')
        return out("the bread of affliction (16:3) — scalded bread and cakes excluded (the Sifrei 130:3); the one who fulfils the duty with a scalded loaf barred from it", ['barred_from_it'])
    if ask == 'the_leaven_on_the_road':
        ink('16:3-4', '"you shall not eat leaven with it … no leavening agent shall be seen with you in all your border seven days" — 16:4 shares Exodus 13:7\'s six tokens in order %s' % (SHARED(D16(4), ('Exod', 13, 7)),))
        move('MISHNAH PESACHIM 3:7 (read whole at the design — THE EXAM ROW); cold_run_pesach (CALL) — the window %s' % (CA_MATZAH,), "THE LEAVEN REMEMBERED ON THE ROAD — one traveling to slaughter his Passover, to circumcise his son or to eat a betrothal feast who remembers leaven in his house: if he can return and remove and return to the errand, he returns and removes; if not, he nullifies it in his heart; to save from gentiles, a river, bandits, fire or a collapse — he nullifies; for an optional Sabbath residence — he returns at once: THREE ARMS on the Mishnah's own line")
        dat('the leaven on the road a DATA row (the_leaven_on_the_road — three arms); the exam\'s person the traveler to his son\'s circumcision with time to return — accepted when he returns and removes')
