        ink('16:16', '"THREE TIMES A YEAR all your males shall appear before the LORD your God in the place which He will choose" — the parser\'s [3] %s ("three" spelled full — the diff with Exodus 34:23 %s); Exodus 34:23\'s eight in order, 23:17\'s seven %s; 2 Chronicles 8:13 the one other verse with the three names in order (asserted at the reading)' % (PARSE[16][0], DIFF(D16(16), ('Exod', 34, 23))[0], (TWIN['16:16 vs Exod 34:23'], TWIN['16:16 vs Exod 23:17'])))
