def the_judges_in_every_gate(case, data):
    """F5 — Deut 16:18-20 — THE LINE judges_in_every_gate_commanded writing judges_and_officers_commanded and justice_pursuit_commanded (STATUSES), judgment_wresting_barred and person_respecting_barred (BLOCKS) and bribe_barred (its FIRST entry); the three tiers and the acquittal final PARAMETERS; the courts by CALL (exodus_story, opening_speech, ordinances, holiness, second_tablets)"""
