        dat('THE WRITE judges_and_officers_commanded — a STATUS on israel_people at the counter\'s day (DH2); the exam\'s person the community that appoints a court for all Israel — accepted')
        return out("the court for all Israel (16:18) — judges and officers 'for yourself' (the Sifrei 144:1; exodus_story.jethro %s judges, the sizes %s by CALL): THE WRITE judges_and_officers_commanded, a STATUS on Israel at the chapter's own day; the community that appoints the court accepted" % (ES_JUDGES, ES_SIZES), ['judges_and_officers_commanded'])
